<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_role('admin');$id=get_int('id');$s=db()->prepare('SELECT e.*,s.title subject_title,c.title class_title FROM exams e LEFT JOIN subjects s ON s.id=e.subject_id LEFT JOIN classes c ON c.id=e.class_id WHERE e.id=?');$s->execute([$id]);$exam=$s->fetch();if(!$exam){http_response_code(404);exit('آزمون پیدا نشد.');}$s=db()->prepare('SELECT q.*,GROUP_CONCAT(CONCAT(o.option_key,": ",o.option_text) ORDER BY o.sort_order SEPARATOR " | ") options_text FROM questions q LEFT JOIN question_options o ON o.question_id=q.id WHERE q.exam_id=? GROUP BY q.id ORDER BY q.sort_order,q.id');$s->execute([$id]);$questions=$s->fetchAll();$title='پیش‌نمایش آزمون';require __DIR__.'/../partials/header.php';?><div class="card"><span class="eyebrow">پیش‌نمایش مدیر</span><h1><?=e($exam['title'])?></h1><p class="muted"><?=e($exam['subject_title']??'بدون درس')?> — <?=e($exam['class_title']??'بدون کلاس')?> — مدت: <?=e((string)$exam['duration_minutes'])?> دقیقه — وضعیت: <span class="badge"><?=e($exam['status'])?></span></p><?php if($exam['instructions']):?><div class="alert warning"><?=nl2br(e($exam['instructions']))?></div><?php endif;?></div><div class="card"><h2>پرسش‌ها</h2><?php if(!$questions):?><p class="muted">این آزمون هنوز پرسشی ندارد.</p><?php else:foreach($questions as $i=>$q):?><article class="question"><strong><?=($i+1).'. '.e($q['question_text'])?></strong><p class="muted">نوع: <?=e($q['question_type'])?> — نمره: <?=format_score($q['score'])?></p><?php if($q['options_text']):?><div class="option-list"><?php foreach(explode(' | ',$q['options_text']) as $option):?><div class="option"><span><?=e($option)?></span></div><?php endforeach;?></div><?php endif;?><?php if($q['question_type']==='short'):?><div class="answer-placeholder">پاسخ تشریحی دانش‌آموز در این بخش وارد می‌شود.</div><?php endif;?></article><?php endforeach;endif;?></div><div class="actions"><a class="btn btn-primary" href="<?=e(url('teacher/exams.php?id='.$id))?>">مدیریت پرسش‌ها</a><a class="btn btn-light" href="<?=e(url('admin/exams.php'))?>">بازگشت</a></div><?php require __DIR__.'/../partials/footer.php'; ?>
